    'web.challenge.status.finalist.h': 'Sie stehen auf der Shortlist – präsentieren am 13. August 🎯',
    'web.challenge.status.finalist.p': 'Ihr Beitrag hat es in die engere Auswahl geschafft und Sie sind eingeladen, ihn beim Demo Day live zu präsentieren. Die Preise werden am Abend vergeben: Jeder, der dabei ist und eine Präsentation abschließt, gewinnt etwas, wobei die Rangfolge durch eine Publikumsabstimmung festgelegt wird. Das Nichterscheinen gilt als verwirkt – die Preisverleihung erfolgt ausschließlich auf der Bühne.',
