    'web.challenge.status.notSelected.p': 'Ihre Einreichung gehört diesmal nicht zu den Präsentationen, aber Ihr Teilnahmeplatz bleibt reserviert; eine weitere Anmeldung ist nicht erforderlich. Wir würden uns freuen, Sie dort zu sehen – kommen Sie vorbei, sehen Sie, was alle gebaut haben, und teilen Sie, was Sie mit KI-Agenten entwickelt haben. Die endgültige Rangliste hängt ebenfalls von der Publikumsabstimmung ab, an der Sie einmal teilnehmen können.',
