    'web.challenge.f.dir.ph': 'z.B. Ein Rechercheagent, der eine wöchentliche RSS- und Web-Suche in ein Mitbewerber-Briefing umwandelt.',
    'web.challenge.f.dir.help': 'Ein oder zwei Sätze zu Ihrer Idee. Sie können es verfeinern, sobald Sie mit dem Bau beginnen.',
