    'web.landing.machinesTitleAccent': 'überall aus.',
    'web.landing.machinesBody': 'Richten Sie in Sekundenschnelle einen Arbeitsbereich ein, lassen Sie ihn laufen oder vernetzen Sie Ihre eigenen Maschinen. Mischen Sie alle drei; Manyfold behandelt sie gleich.',
    'web.landing.machineCloudName1': 'Probieren Sie es',
    'web.landing.machineCloudName2': 'sofort aus',
    'web.landing.machineCloudBody': 'Ein neuer Arbeitsbereich in Sekundenschnelle. Perfekt für schnelle Aufgaben und Experimente – schließen Sie es, wenn Sie fertig sind und nichts aufräumen müssen.',
