    'web.landing.machineLocalName1': 'Halten Sie es',
    'web.landing.machineLocalName2': 'am Laufen',
    'web.landing.machineLocalBody': 'Ein Arbeitsbereich, der zwischen den Besuchen wach bleibt. Ihre Dateien, Tools und Sitzungen sind genau dort, wo Sie sie verlassen haben – bereit für die weitere Arbeit.',
    'web.landing.machineLocalTag1': 'Gehostet',
