    'web.channels.settings.tooltips.reregisterTelegram': 'setWebhook auf Telegram erneut ausführen',
    'web.channels.settings.tooltips.refreshLarkIdentity': 'Die für die @-Erkennung verwendete Bot-Identität abrufen',
    'web.channels.settings.tooltips.registerWeixin': 'iLink-Bot-Token prüfen und Kanal aktivieren',
    'web.channels.settings.tooltips.registerLinear': 'App-Token erstellen, Linear-Identität erfassen und Kanal aktivieren',
    'web.channels.settings.tooltips.registerGithub': 'App-Anmeldedaten prüfen, App-Identität erfassen und Kanal aktivieren',
    'web.channels.settings.tooltips.registerMatrix': 'Matrix-whoami prüfen und Kanal aktivieren',
    'web.channels.settings.tooltips.registerLine': 'Webhook-URL auf LINE setzen, Bot-Identität erfassen und Kanal aktivieren',
    'web.channels.settings.placeholders.teamSupport': 'z. B. team-support',
    'web.channels.settings.placeholders.linearClientId': 'aus Ihrer Linear-Anwendung',
    'web.channels.settings.placeholders.linearAccessToken': 'Token anstelle eines Client-Paars einfügen',
    'web.channels.settings.placeholders.organizationOptional': 'Organisation (optional)',
    'web.channels.settings.placeholders.privateKey': '-----BEGIN RSA PRIVATE KEY----- (oder Base64 davon)',
    'web.channels.settings.placeholders.delegationLabel': 'z. B. agent',
    'web.channels.settings.setupMode.lark': 'Lark-Einrichtungsmodus',
    'web.channels.settings.setupMode.weixin': 'WeChat-Einrichtungsmodus',
    'web.channels.settings.help.telegramCreate': 'Erstellen Sie über @BotFather einen Bot und fügen Sie das Token ein. Wir registrieren den Webhook für Sie.',
    'web.channels.settings.help.telegramEdit': 'Lassen Sie erlaubte Benutzer oder Gruppenchats leer, um allen Zugriff zu gewähren. Operatoren können agentenweite Befehle wie /model ausführen; ohne Operatoren sind diese Befehle in Telegram deaktiviert.',
    'web.channels.settings.help.slackCreate': 'Fügen Sie nach dem Speichern die eingehende Kanal-URL in Ihrer Slack-App unter Event Subscriptions ein. Lassen Sie erlaubte Benutzer leer, damit jeder im Workspace den Bot verwenden kann. Operatoren können agentenweite Befehle wie /model ausführen; ohne Operatoren ist /model in Slack deaktiviert.',
    'web.channels.settings.help.slackEdit': 'Lassen Sie erlaubte Benutzer leer, damit jeder im Workspace den Bot verwenden kann. Operatoren können agentenweite Befehle wie /model ausführen; ohne Operatoren ist /model in Slack deaktiviert.',
    'web.channels.settings.help.linearCreate': 'Erstellen Sie eine Anwendung in Ihrem Linear-Workspace, aktivieren Sie Webhooks mit Agent-Session-Ereignissen und fügen Sie nach dem Speichern dort die eingehende Kanal-URL ein. Mit Client-Anmeldedaten kann Manyfold ein eigenes App-Token erstellen; geben Sie stattdessen ein Zugriffstoken an, wenn Sie selbst eines erstellt haben. Lassen Sie erlaubte Benutzer leer, damit jeder im Workspace den Agenten erwähnen kann.',
    'web.channels.settings.help.githubCreate': 'Erstellen Sie zuerst den Kanal und verwenden Sie dann auf seiner Seite „GitHub App erstellen“ — GitHub sendet die App-Anmeldedaten automatisch zurück. Erwähnen Sie die App in einem Issue, um eine Runde zu starten. Lassen Sie Repositorys leer, damit sie auf jedem Repository antwortet, auf dem die App installiert ist.',
    'web.channels.settings.help.discordCreate': 'Discord verwendet ein Gateway-WebSocket — keine öffentliche URL erforderlich. Aktivieren Sie die MESSAGE_CONTENT-Absicht im Developer Portal unter Bot → Privileged Gateway Intents, sonst sieht der Bot keinen Nachrichtentext.',
    'web.channels.settings.help.matrixCreate': 'Matrix verwendet Long-Polling über /sync — keine Webhook-URL erforderlich. Verschlüsselte Räume werden nicht unterstützt; verschlüsselte Ereignisse werden verworfen.',
    'web.channels.settings.help.weixinCreate': 'Persönliches WeChat über das Tencent-iLink-Bot-Gateway — nur Direktnachrichten, keine Webhook-URL erforderlich. Lassen Sie Operator-IDs leer, um agentenweite Befehle zu deaktivieren.',
    'web.channels.settings.help.larkManual': 'Lassen Sie erlaubte Benutzer leer, damit jeder den Bot erreichen kann. Operatoren können agentenweite Befehle wie /model ausführen; ohne Operatoren ist /model in Feishu/Lark deaktiviert.',
    'web.channels.settings.help.weixinEdit': 'Persönliches WeChat unterstützt nur Direktnachrichten. Lassen Sie Operator-IDs leer, um agentenweite Befehle (z. B. /model) zu deaktivieren.',
    'web.channels.settings.help.whatsappEdit': 'WhatsApp wird über WhatsApp Web verknüpft, dieser Kanal braucht also keine Webhook-URL. Lass erlaubte Absender oder Gruppenchats leer, um niemanden einzuschränken. Operatoren können agentenweite Befehle wie /model ausführen; ohne Operatoren sind diese Befehle in WhatsApp deaktiviert. Absender können als Telefonnummer oder als JID angegeben werden.',
    'web.channels.settings.help.linearEdit': 'Die Aktivität zeigt Gedanken, Tool-Aufrufe und den Plan in der Linear-Sitzung, während der Agent arbeitet; „Nur abschließend“ veröffentlicht nur das Ergebnis. Beim Wechsel der Anmeldedaten werden alle gleichzeitig ersetzt, daher muss das Signaturgeheimnis bei jeder Änderung erneut eingegeben werden.',
    'web.channels.settings.help.githubEdit': 'Leere erlaubte Logins greifen auf die Zuordnungssperre zurück (standardmäßig Repository-Besitzer, Organisationsmitglieder und Mitwirkende — fügen Sie NONE hinzu, um sie zu öffnen). Wenn Sie die Delegierungsbezeichnung zu einem Issue hinzufügen, startet eine Runde ohne Erwähnung. Lassen Sie Operator-Logins leer, um agentenweite Befehle (z. B. /model) zu deaktivieren.',
    'web.channels.settings.help.lineCreate': 'Erstellen Sie in der LINE-Developers-Konsole einen Messaging-API-Kanal, geben Sie ein langlebiges Channel Access Token aus und fügen Sie beides hier ein. Wir setzen die Webhook-URL für Sie — „Use webhook“ müssen Sie weiterhin selbst in der Konsole aktivieren. Antworten sind reiner Text ohne Live-Vorschau, und jede zählt gegen das Nachrichtenkontingent Ihres LINE-Tarifs.',
    'web.channels.settings.help.lineEdit': 'Lassen Sie erlaubte Benutzer oder Gruppen-IDs leer, um allen Zugriff zu gewähren. Operatoren können agentenweite Befehle wie /model ausführen; ohne Operatoren sind diese Befehle in LINE deaktiviert. Beim Rotieren werden beide Anmeldedaten gleichzeitig ersetzt, geben Sie Channel Secret und Access Token also zusammen erneut ein.',
    'web.channels.settings.errors.larkWebhookCredentials': 'Webhook-Kanäle von Lark/Feishu benötigen ein Verifizierungstoken oder einen Verschlüsselungsschlüssel.',
    'web.channels.settings.errors.linearCredentials': 'Linear benötigt entweder ein Zugriffstoken oder sowohl eine Client-ID als auch ein Client-Secret.',
    'web.channels.settings.errors.matrixHomeserver': 'Die Matrix-Homeserver-URL ist erforderlich.',
    'web.channels.settings.errors.matrixAccessToken': 'Das Matrix-Zugriffstoken ist erforderlich.',
    'web.channels.settings.errors.slackCredentials': 'Für die Slack-Tokenrotation werden sowohl Bot-Token als auch Signaturgeheimnis benötigt.',
    'web.channels.settings.errors.linearRotation': 'Für die Rotation der Linear-Anmeldedaten werden das Webhook-Signaturgeheimnis sowie entweder ein Zugriffstoken oder sowohl Client-ID als auch Client-Secret benötigt.',
    'web.channels.settings.errors.githubRotation': 'Für die Rotation der GitHub-Anmeldedaten werden App-ID, privater Schlüssel und Webhook-Geheimnis gemeinsam benötigt.',
    'web.channels.settings.errors.weixinBotToken': 'Das WeChat-iLink-Bot-Token ist erforderlich.',
    'web.channels.settings.errors.lineCredentials': 'LINE benötigt sowohl ein Channel Secret als auch ein Channel Access Token.',
    'web.channels.settings.errors.lineRotation': 'Die Rotation der LINE-Anmeldedaten benötigt Channel Secret und Channel Access Token zusammen.',
    'web.channels.settings.errors.unsupportedProvider': 'Nicht unterstützter Kanalanbieter: {{provider}}.',
